func (q *Queries) UpdateRepository(ctx context.Context, arg UpdateRepositoryParams) (Repository, error) {
	row := q.db.QueryRow(ctx, updateRepository,
		arg.SetCredentialID,
		arg.CredentialID,
		arg.SetGlobalCredentialID,
		arg.GlobalCredentialID,
		arg.DefaultBranch,
		arg.BranchPolicy,
		arg.FetchConfig,
		arg.SetSyncCron,
		arg.SyncCron,
		arg.SetNote,
		arg.Note,
		arg.UpdatedAt,
		arg.TenantID,
		arg.ID,
		arg.ExpectedRevision,
	)
	var i Repository
	err := row.Scan(
		&i.TenantID,
		&i.ID,
		&i.Url,
		&i.CanonicalUrl,
		&i.CredentialID,
		&i.GlobalCredentialID,
		&i.DefaultBranch,
		&i.BranchPolicy,
		&i.FetchConfig,
		&i.SyncCron,
		&i.Note,
		&i.WebhookSecretHash,
		&i.Health,
		&i.Revision,
		&i.DeletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
